+type Promotion struct {
+	ID             string `json:"id"`
+	Name           string `json:"name"`
+	Rules          []Rule `json:"rules"`
+	BudgetTotalCents int64 `json:"budget_total_cents"`
+	BudgetUsedCents  int64 `json:"budget_used_cents"`
